import re, glob
files = {f.replace('wiki/','').rsplit('.md',1)[0].lower() for f in glob.glob('wiki/**/*.md',recursive=True)}
d=0
for f in glob.glob('wiki/**/*.md',recursive=True):
    for l in re.findall(r'\[\[([^\]]+?)(?:\|[^\]]+)?\]\]', open(f).read()):
        target = l.strip().lower()
        if not any(target == s or target == s.split('/')[-1] for s in files):
            print(f'DEAD: {f}: [[{l.strip()}]]')
            d+=1
print(f'OK' if d==0 else f'{d} DEAD')
